61→func (g *Gemini) StartSession(ctx context.Context, dir string) (Session, error) {
62→	name := fmt.Sprintf("gemini-test-%d", time.Now().UnixNano())
63→	s, err := NewTmuxSession(name, dir, nil, "env", "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "gemini", "-y")
64→	if err != nil {
65→		return nil, err
66→	}
67→
68→	// Dismiss startup dialogs (workspace trust, etc.)
69→	for i := 0; i < 5; i++ {
70→		content, err := s.WaitFor(`(Type your message|trust)`, 15*time.Second)
71→		if err != nil {
72→			return s, fmt.Errorf("waiting for startup prompt: %w", err)
73→		}
74→		if !strings.Contains(content, "trust") {
75→			break
76→		}
77→		_ = s.SendKeys("Enter")
78→		time.Sleep(500 * time.Millisecond)
79→	}
80→	s.stableAtSend = ""
81→
82→	return s, nil
83→}
