  1→package agents
  2→
  3→import (
  4→	"fmt"
  5→	"os/exec"
  6→	"regexp"
  7→	"strings"
  8→	"time"
  9→)
 10→
 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string // stable content snapshot when Send was last called
 15→}
 16→
 17→// NewTmuxSession creates a new tmux session running the given command in dir.
 18→// unsetEnv lists environment variable names to strip from the session.
 19→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 20→	s := &TmuxSession{name: name}
 21→
 22→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 23→	// Build the shell command, prefixed with env -u for each var to strip.
 24→	shellCmd := ""
 25→	for _, v := range unsetEnv {
 26→		shellCmd += "env -u " + v + " "
 27→	}
 28→	shellCmd += command
 29→	for _, a := range args {
 30→		shellCmd += " " + a
 31→	}
 32→	tmuxArgs = append(tmuxArgs, shellCmd)
 33→
 34→	cmd := exec.Command("tmux", tmuxArgs...)
 35→	if out, err := cmd.CombinedOutput(); err != nil {
 36→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 37→	}
 38→	// Keep the pane around after the command exits so we can capture error output.
 39→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 40→	_ = setCmd.Run()
 41→	return s, nil
 42→}
 43→
 44→func (s *TmuxSession) Send(input string) error {
 45→	s.stableAtSend = stableContent(s.Capture())
 46→	// Send text and Enter separately — Claude's TUI can swallow Enter
 47→	// if it arrives before the input handler finishes processing the text.
 48→	if err := s.SendKeys(input); err != nil {
 49→		return err
 50→	}
 51→	time.Sleep(200 * time.Millisecond)
 52→	return s.SendKeys("Enter")
 53→}
 54→
 55→// SendKeys sends raw tmux key names without appending Enter.
 56→func (s *TmuxSession) SendKeys(keys ...string) error {
 57→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 58→	cmd := exec.Command("tmux", args...)
 59→	out, err := cmd.CombinedOutput()
 60→	if err != nil {
 61→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 62→	}
 63→	return nil
 64→}
 65→
 66→const settleTime = 2 * time.Second
 67→
 68→// stableContent returns the content with the last few lines stripped,
 69→// so that TUI status bar updates don't prevent the settle timer.
 70→func stableContent(content string) string {
 71→	lines := strings.Split(content, "\n")
 72→	if len(lines) > 3 {
 73→		lines = lines[:len(lines)-3]
 74→	}
 75→	return strings.Join(lines, "\n")
 76→}
 77→
 78→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
 79→	re, err := regexp.Compile(pattern)
 80→	if err != nil {
 81→		return "", fmt.Errorf("invalid pattern: %w", err)
 82→	}
 83→
 84→	deadline := time.Now().Add(timeout)
 85→	var matchedAt time.Time
 86→	var lastStable string
 87→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
 88→
 89→	for time.Now().Before(deadline) {
 90→		content := s.Capture()
 91→		stable := stableContent(content)
 92→
 93→		if !re.MatchString(content) {
 94→			// Pattern lost — reset
 95→			matchedAt = time.Time{}
 96→			lastStable = ""
 97→			time.Sleep(500 * time.Millisecond)
 98→			continue
 99→		}
100→
101→		// Detect content change since Send was called
102→		if !contentChanged && stable != s.stableAtSend {
103→			contentChanged = true
104→		}
105→
106→		if stable != lastStable {
107→			// Pattern matches but content is still changing — reset settle timer
108→			matchedAt = time.Now()
109→			lastStable = stable
110→			time.Sleep(500 * time.Millisecond)
111→			continue
112→		}
113→
114→		// Pattern matches and content hasn't changed since matchedAt.
115→		// Only settle if content changed at least once after Send
116→		// (prevents false settle on echoed input before agent starts).
117→		if contentChanged && time.Since(matchedAt) >= settleTime {
118→			return content, nil
119→		}
120→
121→		time.Sleep(500 * time.Millisecond)
122→	}
123→	content := s.Capture()
124→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
125→}
126→
127→func (s *TmuxSession) Capture() string {
128→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
129→	out, _ := cmd.Output()
130→	return strings.TrimRight(string(out), "\n")
131→}
132→
133→func (s *TmuxSession) Close() error {
134→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
135→	out, err := cmd.CombinedOutput()
136→	if err != nil {
137→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
138→	}
139→	return nil
140→}
141→

  1→package entire
  2→
  3→import (
  4→	"encoding/json"
  5→	"os"
  6→	"os/exec"
  7→	"strings"
  8→	"testing"
  9→)
 10→
 11→// RewindPoint represents a single entry from `entire rewind --list`.
 12→type RewindPoint struct {
 13→	ID             string `json:"id"`
 14→	Message        string `json:"message"`
 15→	MetadataDir    string `json:"metadata_dir"`
 16→	Date           string `json:"date"`
 17→	IsLogsOnly     bool   `json:"is_logs_only"`
 18→	CondensationID string `json:"condensation_id"`
 19→	SessionID      string `json:"session_id"`
 20→}
 21→
 22→// Enable runs `entire enable` for the given agent with telemetry disabled.
 23→// Strategy defaults to "manual-commit" if empty.
 24→func Enable(t *testing.T, dir, agent, strategy string) {
 25→	t.Helper()
 26→	if strategy == "" {
 27→		strategy = "manual-commit"
 28→	}
 29→	run(t, dir, "enable", "--agent", agent, "--strategy", strategy, "--telemetry=false")
 30→}
 31→
 32→// Disable runs `entire disable` in the given directory.
 33→func Disable(t *testing.T, dir string) {
 34→	t.Helper()
 35→	run(t, dir, "disable")
 36→}
 37→
 38→// RewindList runs `entire rewind --list` and parses the JSON output.
 39→func RewindList(t *testing.T, dir string) []RewindPoint {
 40→	t.Helper()
 41→	out := run(t, dir, "rewind", "--list")
 42→
 43→	var points []RewindPoint
 44→	if err := json.Unmarshal([]byte(out), &points); err != nil {
 45→		t.Fatalf("parse rewind list: %v\nraw output: %s", err, out)
 46→	}
 47→	return points
 48→}
 49→
 50→// Rewind runs `entire rewind --to <id>`. Returns an error instead of
 51→// failing the test, since callers may test failure cases.
 52→func Rewind(t *testing.T, dir, id string) error {
 53→	t.Helper()
 54→	return runErr(dir, "rewind", "--to", id)
 55→}
 56→
 57→// RewindLogsOnly runs `entire rewind --to <id> --logs-only`.
 58→func RewindLogsOnly(t *testing.T, dir, id string) error {
 59→	t.Helper()
 60→	return runErr(dir, "rewind", "--to", id, "--logs-only")
 61→}
 62→
 63→// run executes an `entire` subcommand in dir and fails the test on error.
 64→func run(t *testing.T, dir string, args ...string) string {
 65→	t.Helper()
 66→	cmd := exec.Command("entire", args...)
 67→	cmd.Dir = dir
 68→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 69→
 70→	out, err := cmd.CombinedOutput()
 71→	if err != nil {
 72→		t.Fatalf("entire %s failed: %v\n%s", strings.Join(args, " "), err, out)
 73→	}
 74→	return strings.TrimSpace(string(out))
 75→}
 76→
 77→// runErr executes an `entire` subcommand in dir and returns any error.
 78→func runErr(dir string, args ...string) error {
 79→	cmd := exec.Command("entire", args...)
 80→	cmd.Dir = dir
 81→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 82→
 83→	out, err := cmd.CombinedOutput()
 84→	if err != nil {
 85→		return &ExecError{
 86→			Args:   args,
 87→			Err:    err,
 88→			Output: string(out),
 89→		}
 90→	}
 91→	return nil
 92→}
 93→
 94→// ExecError wraps an entire CLI execution failure with its output.
 95→type ExecError struct {
 96→	Args   []string
 97→	Err    error
 98→	Output string
 99→}
100→
101→func (e *ExecError) Error() string {
102→	return "entire " + strings.Join(e.Args, " ") + ": " + e.Err.Error() + "\n" + e.Output
103→}
104→
105→func (e *ExecError) Unwrap() error {
106→	return e.Err
107→}
108→
109→// Explain runs `entire explain --checkpoint <id>` and returns the output.
110→func Explain(t *testing.T, dir, checkpointID string) string {
111→	t.Helper()
112→	return run(t, dir, "explain", "--checkpoint", checkpointID)
113→}
114→
115→// ExplainGenerate runs `entire explain --checkpoint <id> --generate`.
116→// Returns (output, error) — doesn't fail test since callers may test failure cases.
117→func ExplainGenerate(dir, checkpointID string) (string, error) {
118→	return runOutput(dir, "explain", "--checkpoint", checkpointID, "--generate")
119→}
120→
121→// ExplainCommit runs `entire explain --commit <ref>`.
122→// Returns (output, error) — for testing failure cases.
123→func ExplainCommit(dir, ref string) (string, error) {
124→	return runOutput(dir, "explain", "--commit", ref)
125→}
126→
127→// runOutput executes an `entire` subcommand and returns (output, error).
128→func runOutput(dir string, args ...string) (string, error) {
129→	cmd := exec.Command("entire", args...)
130→	cmd.Dir = dir
131→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
132→
133→	out, err := cmd.CombinedOutput()
134→	if err != nil {
135→		return string(out), &ExecError{
136→			Args:   args,
137→			Err:    err,
138→			Output: string(out),
139→		}
140→	}
141→	return strings.TrimSpace(string(out)), nil
142→}
143→

  1→package testutil
  2→
  3→import (
  4→	"fmt"
  5→	"os"
  6→	"os/exec"
  7→	"path/filepath"
  8→	"regexp"
  9→	"strings"
 10→	"testing"
 11→	"time"
 12→)
 13→
 14→// ArtifactRoot is the absolute path to the artifact output directory.
 15→// Must be set in TestMain before any tests run.
 16→var ArtifactRoot string
 17→
 18→// ArtifactTimestamp is the timestamp subdirectory for this test run.
 19→var ArtifactTimestamp = time.Now().Format("2006-01-02T15-04-05")
 20→
 21→var runDirOverride string
 22→
 23→// SetRunDir overrides the artifact run directory (e.g. from E2E_ARTIFACT_DIR).
 24→func SetRunDir(dir string) {
 25→	runDirOverride = dir
 26→}
 27→
 28→// ArtifactRunDir returns the directory for the current test run.
 29→func ArtifactRunDir() string {
 30→	if runDirOverride != "" {
 31→		return runDirOverride
 32→	}
 33→	return filepath.Join(ArtifactRoot, ArtifactTimestamp)
 34→}
 35→
 36→func artifactDir(t *testing.T) string {
 37→	t.Helper()
 38→	name := strings.ReplaceAll(t.Name(), "/", "-")
 39→	dir := filepath.Join(ArtifactRunDir(), name)
 40→	if err := os.MkdirAll(dir, 0o755); err != nil {
 41→		t.Logf("warning: failed to create artifact dir: %v", err)
 42→	}
 43→	return dir
 44→}
 45→
 46→// CaptureArtifacts captures git state, checkpoint metadata, entire logs,
 47→// and console output to the artifact directory.
 48→func CaptureArtifacts(t *testing.T, s *RepoState) {
 49→	t.Helper()
 50→	dir := s.ArtifactDir
 51→
 52→	writeArtifact(t, dir, "git-log.txt",
 53→		gitOutputSafe(s.Dir, "log", "--decorate", "--graph", "--all"))
 54→
 55→	writeArtifact(t, dir, "git-tree.txt",
 56→		gitOutputSafe(s.Dir, "ls-tree", "-r", "HEAD")+
 57→			"\n--- entire/checkpoints/v1 ---\n"+
 58→			gitOutputSafe(s.Dir, "ls-tree", "-r", "entire/checkpoints/v1"))
 59→
 60→	// console.log is written incrementally to disk via s.ConsoleLog (*os.File),
 61→	// so it already exists in the artifact dir and survives global timeouts.
 62→
 63→	if t.Failed() {
 64→		writeArtifact(t, dir, "FAIL", "")
 65→	} else {
 66→		writeArtifact(t, dir, "PASS", "")
 67→	}
 68→
 69→	captureCheckpointMetadata(t, s, dir)
 70→	captureEntireLogs(t, s.Dir, dir)
 71→
 72→	if os.Getenv("E2E_KEEP_REPOS") != "" {
 73→		link := filepath.Join(dir, "repo")
 74→		if err := os.Symlink(s.Dir, link); err != nil {
 75→			t.Logf("warning: failed to symlink repo: %v", err)
 76→		}
 77→	}
 78→}
 79→
 80→func captureCheckpointMetadata(t *testing.T, s *RepoState, outDir string) {
 81→	t.Helper()
 82→	commits := NewCheckpointCommits(t, s)
 83→	metaDir := filepath.Join(outDir, "checkpoint-metadata")
 84→
 85→	cpIDRe := regexp.MustCompile(`(?m)^Checkpoint:\s+(\S+)`)
 86→	for _, sha := range commits {
 87→		msg := gitOutputSafe(s.Dir, "log", "-1", "--format=%B", sha)
 88→		m := cpIDRe.FindStringSubmatch(msg)
 89→		if m == nil || len(m[1]) < 3 {
 90→			continue
 91→		}
 92→		id := m[1]
 93→		cpPath := CheckpointPath(id)
 94→
 95→		cpDir := filepath.Join(metaDir, cpPath)
 96→		_ = os.MkdirAll(cpDir, 0o755)
 97→		raw := gitOutputSafe(s.Dir, "show", sha+":"+cpPath+"/metadata.json")
 98→		writeArtifact(t, cpDir, "metadata.json", raw)
 99→
100→		for i := 0; ; i++ {
101→			sessPath := fmt.Sprintf("%s/%d/metadata.json", cpPath, i)
102→			raw := gitOutputSafe(s.Dir, "show", sha+":"+sessPath)
103→			if raw == "" {
104→				break
105→			}
106→			sessDir := filepath.Join(cpDir, fmt.Sprintf("%d", i))
107→			_ = os.MkdirAll(sessDir, 0o755)
108→			writeArtifact(t, sessDir, "metadata.json", raw)
109→		}
110→	}
111→}
112→
113→func captureEntireLogs(t *testing.T, repoDir, outDir string) {
114→	t.Helper()
115→	logDir := filepath.Join(repoDir, ".entire", "logs")
116→	entries, err := os.ReadDir(logDir)
117→	if err != nil {
118→		return
119→	}
120→	dst := filepath.Join(outDir, "entire-logs")
121→	_ = os.MkdirAll(dst, 0o755)
122→	for _, e := range entries {
123→		data, err := os.ReadFile(filepath.Join(logDir, e.Name()))
124→		if err != nil {
125→			continue
126→		}
127→		writeArtifact(t, dst, e.Name(), string(data))
128→	}
129→}
130→
131→func writeArtifact(t *testing.T, dir, name, content string) {
132→	t.Helper()
133→	path := filepath.Join(dir, name)
134→	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
135→		t.Logf("warning: failed to write artifact %s: %v", path, err)
136→	}
137→}
138→
139→func gitOutputSafe(dir string, args ...string) string {
140→	cmd := exec.Command("git", args...)
141→	cmd.Dir = dir
142→	out, err := cmd.Output()
143→	if err != nil {
144→		return ""
145→	}
146→	return string(out)
147→}
