115→// ExplainGenerate runs `entire explain --checkpoint <id> --generate`.
116→// Returns (output, error) — doesn't fail test since callers may test failure cases.
117→func ExplainGenerate(dir, checkpointID string) (string, error) {
118→	return runOutput(dir, "explain", "--checkpoint", checkpointID, "--generate")
119→}
120→
121→// ExplainCommit runs `entire explain --commit <ref>`.
122→// Returns (output, error) — for testing failure cases.
123→func ExplainCommit(dir, ref string) (string, error) {
124→	return runOutput(dir, "explain", "--commit", ref)
125→}
126→
127→// runOutput executes an `entire` subcommand and returns (output, error).
128→func runOutput(dir string, args ...string) (string, error) {
129→	cmd := exec.Command("entire", args...)
130→	cmd.Dir = dir
131→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
132→
133→	out, err := cmd.CombinedOutput()
134→	if err != nil {
135→		return string(out), &ExecError{
136→			Args:   args,
137→			Err:    err,
138→			Output: string(out),
139→		}
140→	}
141→	return strings.TrimSpace(string(out)), nil
142→}
