// TestRewindPostCommitLogsOnly: agent creates a file, user commits it.
// Rewind points after a commit should be logs-only and a full rewind
// should be rejected by the CLI.
//
// Currently skipped: ENT-300 — `entire rewind --to` silently succeeds
// for logs-only points instead of erroring.
func TestRewindPostCommitLogsOnly(t *testing.T) {
	testutil.SkipKnownIssue(t, "ENT-300", "entire rewind --to should error for logs-only rewind points")

	testutil.ForEachAgent(t, 3*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		_, err := s.RunPrompt(t, ctx,
			"create a markdown file at docs/red.md with a paragraph about the colour red. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent failed: %v", err)
		}
		testutil.AssertFileExists(t, s.Dir, "docs/red.md")

		// User commits the file.
		s.Git(t, "add", "docs/")
		s.Git(t, "commit", "-m", "Add red.md")

		testutil.WaitForCheckpoint(t, s, 15*time.Second)

		points := entire.RewindList(t, s.Dir)
		require.NotEmpty(t, points, "expected rewind points after commit")

		// Find a logs-only point.
		var logsOnlyPoint *entire.RewindPoint
		for i := range points {
			if points[i].IsLogsOnly {
				logsOnlyPoint = &points[i]
				break
			}
		}
		require.NotNil(t, logsOnlyPoint, "expected at least one logs-only rewind point")

		// Full rewind should fail for a logs-only point.
		err = entire.Rewind(t, s.Dir, logsOnlyPoint.ID)
		assert.Error(t, err, "full rewind to logs-only point should fail")

		// Working directory should be unchanged — file still committed.
		testutil.AssertFileExists(t, s.Dir, "docs/red.md")
	})
}

