// TestSubagentFilesTouchedAcrossCheckpoints: when a subagent modifies a file
// in a second prompt, the second checkpoint's files_touched should include
// that file.
// Bug #329: subagents spawned before startLine offset have their file
// modifications missed in subsequent checkpoints.
func TestSubagentFilesTouchedAcrossCheckpoints(t *testing.T) {
	testutil.SkipKnownIssue(t, "ENT-329", "subagent files missed in subsequent checkpoints")

	testutil.ForEachAgent(t, 5*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		// Prompt 1: subagent creates a file.
		_, err := s.RunPrompt(t, ctx,
			"use a subagent: create a markdown file at docs/red.md with a paragraph about the colour red. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent prompt 1 failed: %v", err)
		}
		testutil.AssertFileExists(t, s.Dir, "docs/red.md")

		s.Git(t, "add", "docs/")
		s.Git(t, "commit", "-m", "Add red.md via subagent")

		testutil.WaitForCheckpoint(t, s, 15*time.Second)
		cpID1 := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID1)

		// Record checkpoint branch position before second prompt.
		cpBranchRef := testutil.GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")

		// Prompt 2: subagent adds content to the same file.
		_, err = s.RunPrompt(t, ctx,
			"use a subagent: add another paragraph to docs/red.md about different shades of red. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent prompt 2 failed: %v", err)
		}

		s.Git(t, "add", "docs/")
		s.Git(t, "commit", "-m", "Update red.md via subagent")

		testutil.WaitForCheckpointAdvanceFrom(t, s.Dir, cpBranchRef, 15*time.Second)

		cpID2 := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")

		// The bug: docs/red.md won't appear in files_touched for the second checkpoint.
		testutil.AssertCheckpointFilesTouchedContains(t, s.Dir, cpID2, "docs/red.md")
	})
}

